-- Référencement initial de structures officiellement documentées.
-- Réexécutable : ignore les noms déjà présents, ne modifie pas les fiches existantes.
DO $add_local_aids$
DECLARE r record;
BEGIN
  PERFORM pg_advisory_xact_lock(84690123);
  FOR r IN
    SELECT * FROM jsonb_to_recordset('[{"nom":"K’DI LE CŒUR — épicerie solidaire de Saint-Leu","categorie":"alimentaire","commune":"Saint-Leu","zone_couverte":"Saint-Leu","organisme":"Association K''DI LE CŒUR (réseau ANDES)","type_dispositif":"aide_alimentaire","description_fr":"Épicerie sociale et solidaire de Saint-Leu : produits de première nécessité et accompagnement budgétaire des familles en précarité. L''accès est soumis à une orientation et à des conditions à confirmer.","description_kreol":"Lépiseri solidèr Sin-Leu i aide bann famiy dann difikilté pou bann produits essentiels ek out bidzé. I fo vérifi bann conditions ek l''association.","demarches_fr":"Contacter l''association et demander comment être orienté vers l''épicerie et quels justificatifs présenter. Vérifier les jours d''accueil avant de se déplacer.","demarches_kreol":"Kontak l''association pou konèt conditions, justificatifs ek zour d''accueil avan déplac aou.","lien_officiel":"https://andes-france.com/structure/kdi-le-coeur/","source_verification":"https://reunion.deets.gouv.fr/L-aide-alimentaire","periode_validite":"Référencement opérateurs alimentaires DEETS 2025-2026 ; conditions et accueil à reconfirmer","score_priorite":100,"besoin_enfant":false,"besoin_locataire":false},{"nom":"FAMI-LIEN — accompagnement des familles UDAF Réunion","categorie":"famille","commune":null,"zone_couverte":"La Réunion","organisme":"UDAF 974","type_dispositif":"accompagnement","description_fr":"Accompagnement gratuit des familles qui rencontrent des difficultés administratives, budgétaires, financières ou relationnelles. Il ne s''agit pas d''une allocation versée.","description_kreol":"FAMI-LIEN i accompagne bann famiy gratis pou difficultés papiers, bidzé, larzan ek relations. Lé pa in allocation versée.","demarches_fr":"Consulter le service FAMI-LIEN de l''UDAF 974 et contacter l''équipe pour connaître l''accueil et les modalités de suivi.","demarches_kreol":"Regarde service FAMI-LIEN UDAF 974 ek kontak l''équipe pou konèt modalités d''accompagnement.","lien_officiel":"https://www.udaf974.fr/fami-lien/","source_verification":"https://www.udaf974.fr/fami-lien/","periode_validite":"Page officielle UDAF publiée le 10 novembre 2026","score_priorite":100,"besoin_enfant":true,"besoin_locataire":false},{"nom":"Comité DAL 974 — accompagnement logement et entraide","categorie":"logement","commune":null,"zone_couverte":"La Réunion ; permanences à Saint-Leu, Saint-Paul et Saint-Gilles-les-Hauts","organisme":"Comité Droit Au Logement (DAL 974)","type_dispositif":"accompagnement","description_fr":"Accompagnement gratuit pour la recherche de logement, les dossiers DALO, les litiges locatifs, les menaces d''expulsion et certaines actions de colis alimentaires. Ne fournit pas directement de logement ni de versement garanti.","description_kreol":"Comité DAL 974 i accompagne gratis pou recherche kaz, dossier DALO, problèmes locataires ek expulsion. Nana osi kèk actions colis alimentaires selon conditions. Li donne pa kaz automatiquement.","demarches_fr":"Prendre rendez-vous par le site officiel. Des permanences sont indiquées à Saint-Leu, Saint-Paul et Saint-Gilles-les-Hauts ; confirmer horaires et lieu avant déplacement.","demarches_kreol":"Pran rendez-vous su site officiel. Nana bann permanences Sin-Leu, Sin-Pol ek Sin-Zil lé O ; vérifi horaires avan allé.","lien_officiel":"https://comitedal974.re/","source_verification":"https://comitedal974.re/","periode_validite":"Services et permanences affichés sur le site consulté en novembre 2026","score_priorite":105,"besoin_enfant":false,"besoin_locataire":true},{"nom":"UNIR OI — aide alimentaire et épicerie solidaire","categorie":"alimentaire","commune":null,"zone_couverte":"La Réunion ; implantation et accès à confirmer auprès de l''association","organisme":"Association UNIR OI","type_dispositif":"aide_alimentaire","description_fr":"Association proposant un accompagnement alimentaire, notamment des distributions adaptées et une épicerie sociale et solidaire. Les modalités d''accès et la commune de distribution sont à confirmer.","description_kreol":"UNIR OI i propose aide alimentaire ek lépiseri solidèr. I fo kontakte zot pou conèt où, quand ek conditions.","demarches_fr":"Contacter UNIR OI via son site officiel pour connaître le dispositif accessible, le lieu, l''orientation et les critères du moment.","demarches_kreol":"Kontak UNIR OI su site officiel pou conèt service, lieu, conditions ek pièces nécessaires.","lien_officiel":"https://unir-oi.re/aide-alimentaire-unir-oi-a-vos-cotes/","source_verification":"https://unir-oi.re/aide-alimentaire-unir-oi-a-vos-cotes/","periode_validite":"Présentation de l''association publiée le 17 juin 2026 ; modalités à reconfirmer","score_priorite":85,"besoin_enfant":false,"besoin_locataire":false},{"nom":"Croix-Rouge française — aide alimentaire à La Réunion","categorie":"alimentaire","commune":null,"zone_couverte":"La Réunion ; antennes locales et distributions selon les sites","organisme":"Croix-Rouge française, délégation territoriale de La Réunion","type_dispositif":"accompagnement","description_fr":"Aide alimentaire, accueil et orientation sociale assurés par les antennes de la Croix-Rouge à La Réunion. Les distributions, lieux et critères varient selon les antennes.","description_kreol":"Croix-Rouge La Rényon i propose aide alimentaire ek orientation sociale selon bann antennes. Vérifi lieux, horaires ek conditions.","demarches_fr":"Consulter la délégation territoriale et contacter l''antenne locale pour vérifier les distributions et l''orientation sociale possibles.","demarches_kreol":"Regarde délégation La Rényon ek kontak l''antenne pli proche pou vérifi distributions ek conditions.","lien_officiel":"https://www.croix-rouge.fr/delegation-territoriale-de-la-reunion","source_verification":"https://www.croix-rouge.fr/delegation-territoriale-de-la-reunion","periode_validite":"Présentation officielle de la délégation consultée en novembre 2026","score_priorite":80,"besoin_enfant":false,"besoin_locataire":false},{"nom":"Secours Catholique de La Réunion — entraide et accompagnement","categorie":"alimentaire","commune":null,"zone_couverte":"La Réunion ; équipes d''accueil locales","organisme":"Secours Catholique - Caritas France, délégation de La Réunion","type_dispositif":"accompagnement","description_fr":"Accueil social, aides d''urgence accompagnées, paniers alimentaires, vêtements, mobilier et soutien aux familles ou personnes en précarité selon évaluation et moyens disponibles.","description_kreol":"Secours Catholique La Rényon i accompagne bann personnes dann difikilté : aide alimentaire, vêtements, mobiliers ek écoute selon situation.","demarches_fr":"Contacter la délégation ou une équipe locale via le site officiel pour expliquer le besoin et les conditions d''accueil.","demarches_kreol":"Kontak délégation ou bann équipes locales su site officiel pou explique out besoin ek vérifi accueil.","lien_officiel":"https://reunion.secours-catholique.org/nos-actions-la-reunion","source_verification":"https://reunion.secours-catholique.org/nos-actions-la-reunion","periode_validite":"Page de la délégation consultée en novembre 2026","score_priorite":80,"besoin_enfant":false,"besoin_locataire":false},{"nom":"Aide et accompagnement à domicile (AAD) — CAF de La Réunion","categorie":"famille","commune":null,"zone_couverte":"La Réunion","organisme":"CAF de La Réunion et services d''aide à domicile partenaires","type_dispositif":"accompagnement","description_fr":"Dispositif d''aide et d''accompagnement à domicile des familles en cas de difficultés ou événements de vie. Une participation financière peut rester due selon la situation et le quotient familial ; ce n''est pas une prime automatiquement versée.","description_kreol":"CAF La Rényon i accompagne bann famiy à domicile selon difficulté ou événement de vie. Nana parfois participation selon ressources ; lé pa in prime automatique.","demarches_fr":"Consulter la page officielle CAF puis demander au service d''aide et d''accompagnement à domicile les conditions et la participation applicables.","demarches_kreol":"Regarde page CAF officielle ek demande au service d''aide à domicile bann conditions ek participation à payer.","lien_officiel":"https://caf.fr/allocataires/caf-de-la-reunion/actualites-departementales/aide-et-accompagnement-domicile-aad-un-soutien-pour-les-familles-la-reunion","source_verification":"https://caf.fr/allocataires/caf-de-la-reunion/actualites-departementales/aide-et-accompagnement-domicile-aad-un-soutien-pour-les-familles-la-reunion","periode_validite":"Article CAF de La Réunion du 18 septembre 2026 ; participation à vérifier","score_priorite":80,"besoin_enfant":true,"besoin_locataire":false},{"nom":"Médiation familiale — UDAF de La Réunion","categorie":"famille","commune":null,"zone_couverte":"La Réunion ; accueil sur rendez-vous","organisme":"UDAF 974","type_dispositif":"accompagnement","description_fr":"Service de médiation familiale en cas de séparation, conflit, tensions ou questions sur les enfants. Le premier entretien d''information est gratuit ; les séances de médiation suivantes peuvent être payantes selon les ressources.","description_kreol":"UDAF i propose médiation famiy pou séparation ou conflits. Premier entretien d''information lé gratis ; lezot séances i pé coûter selon out ressources.","demarches_fr":"Prendre rendez-vous auprès du service médiation familiale de l''UDAF et demander les conditions et le tarif avant les séances.","demarches_kreol":"Pran rendez-vous avèk médiation famiy UDAF ek demande conditions ek tarif avan séances.","lien_officiel":"https://www.udaf974.fr/services-aux-familles/mediation-familiale/","source_verification":"https://www.udaf974.fr/services-aux-familles/mediation-familiale/","periode_validite":"Informations de service consultées en novembre 2026","score_priorite":75,"besoin_enfant":true,"besoin_locataire":false}]'::jsonb)
      AS x(nom text,categorie text,commune text,zone_couverte text,organisme text,
           type_dispositif text,description_fr text,description_kreol text,
           demarches_fr text,demarches_kreol text,lien_officiel text,
           source_verification text,periode_validite text,score_priorite integer,
           besoin_enfant boolean,besoin_locataire boolean)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.aides_reunion a WHERE lower(unaccent(a.nom))=lower(unaccent(r.nom))
    ) THEN
      INSERT INTO public.aides_reunion(
        nom,categorie,commune,zone_couverte,organisme,type_dispositif,
        description,description_fr,description_kreol,demarches_fr,demarches_kreol,
        lien,lien_officiel,source_verification,periode_validite,
        statut_verification,date_verification,score_priorite,
        besoin_enfant,besoin_locataire,actif
      ) VALUES(
        r.nom,r.categorie,r.commune,r.zone_couverte,r.organisme,r.type_dispositif,
        r.description_fr,r.description_fr,r.description_kreol,r.demarches_fr,r.demarches_kreol,
        r.lien_officiel,r.lien_officiel,r.source_verification,r.periode_validite,
        'source_confirmee',date '2026-11-20',r.score_priorite,
        r.besoin_enfant,r.besoin_locataire,true
      );
    END IF;
  END LOOP;
END
$add_local_aids$;